UPDATE companies SET description='Precise Circuits Inc operates from Carrollton, Texas. The company traces its roots to 1995 when it began as a specialist in custom electronic design and manufacturing. In recent years it was acquired by Daburn Electronics, a wire, cable, and power supply manufacturer founded in 1964, which is expanding Precise Circuits'' design and manufacturing operations in Carrollton.

Precise Circuits designs, develops, prototypes, integrates, tests, and manufactures custom electronic assemblies and sub-assemblies. Its in-house capabilities include electronic circuit design, PCB layout, high-temperature testing up to 200°C, wiring harness design and manufacture, and both surface-mount and thru-hole assembly. The company offers turnkey solutions or can participate in specific project phases, focusing on hardware design and the production of small to medium quantities with rapid turnaround. It also sources obsolete components and designs work-arounds or complete replacements. With over 30 years of experience, the firm has developed high-temperature downhole tools for open-hole and production logging, memory tools, and ruggedized equipment for oil-field and mining applications.

The company serves the oil and gas and mining sectors, providing downhole logging tools and ruggedized electronics for harsh environments.

Precise Circuits emphasizes its strength in hardware design coupled with manufacturing of small to medium runs at reasonable cost and quick turnaround. The acquisition by Daburn Electronics adds the resources of a larger organization to enhance R&D, product development, and customer service, while maintaining ISO 9001 and AS9100 quality certifications.', certifications=ARRAY['ISO 9001','AS9100']::text[], profile='{"capabilities": ["Electronic circuit design", "PCB layout", "High-temperature testing (up to 200\u00b0C)", "Wiring harness design and manufacture", "Surface-mount assembly", "Thru-hole assembly", "Prototyping", "Integration", "Testing", "Turnkey manufacturing", "Obsolete component sourcing", "Work-around design", "Downhole tool design", "Ruggedized equipment design"], "industries": ["Oil and gas", "Mining", "Downhole logging", "Production logging"], "materials": [], "equipment": [], "volume": "Small to medium quantities", "lead_time": "", "tolerances": "", "built_on": ["In-house electronic circuit design and PCB layout", "High-temperature testing up to 200\u00b0C", "Wiring harness design and manufacture", "Surface-mount and thru-hole assembly with rapid turnaround for small to medium quantities", "Over 30 years experience in downhole tools for oil and gas"], "facts_used": ["Founded in 1995 -> /", "Headquarters in Carrollton, TX -> /", "Acquired by Daburn Electronics -> /", "Capabilities: electronic circuit design, PCB layout, high temperature testing up to 200\u00b0C, wiring harness design and manufacture, surface-mount and thru-hole assembly -> /", "Industries: oil and gas, mining, downhole logging -> /", "Certifications: ISO 9001, AS9100 -> / and db", "Strengths: hardware design and manufacture of small to medium quantities at reasonable cost with rapid turnaround -> /", "Obsolete component sourcing and replacement design -> /", "Over 30 years experience in downhole tools for oil and gas -> /", "Daburn Electronics founded 1964 -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Precise Circuits designs, develops, prototypes, integrates, tests and manufactures custom electronic assemblies and sub assemblies.", "founded_year": "1995", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='precise-circuits-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Precision Architectural Metals, Inc. (PAM) was founded in 1994 as a division of Georgetown Roofing, Inc. in Capitol Heights, Maryland. The company operates as a veteran-owned, service-disabled small business from a 40,000-square-foot facility in nearby Hyattsville, Maryland, just outside Washington, D.C.

PAM specializes in architectural sheet metal fabrication, offering large-volume brake forming, custom fabrication of unusual and antique items, and CNC plasma cutting. The shop stocks more than 150 colors, materials, and gauges of architectural sheet metal, including Kynar-coated products from manufacturers. Computer-controlled equipment and a patented fabrication process enable production of virtually any item detailed in the SMACNA architectural sheet metal manual.

The company serves customers throughout the mid-Atlantic region, ranging from single-person operations to large commercial contractors.

PAM differentiates itself with a 24- to 48-hour turnaround on most orders—far faster than the typical six- to eight-week lead times of out-of-town fabricators. The combination of extensive local inventory, high-tech equipment, and a patented process allows the company to fill orders quickly at competitive prices.', certifications=ARRAY['Veteran Owned Service Disabled Small Business']::text[], profile='{"capabilities": ["Sheet metal brake forming", "Custom sheet metal fabrication", "CNC plasma cutting", "Architectural sheet metal fabrication", "SMACNA-compliant fabrication", "Kynar coated metal fabrication", "Large volume sheet metal forming", "Antique and unusual item fabrication"], "industries": ["Architectural sheet metal", "Roofing", "Commercial construction", "General contracting"], "materials": ["Architectural sheet metal (various colors, gauges)", "Kynar coated metal"], "equipment": ["CNC plasma cutting equipment", "Computer-controlled fabrication equipment"], "volume": "", "lead_time": "24-48 hours for most orders", "tolerances": "", "built_on": ["24- to 48-hour turnaround on most orders", "Stocks over 150 colors, materials, and gauges of architectural sheet metal", "40,000 sq ft facility with computer-controlled fabrication equipment", "Patented fabrication process", "Veteran-owned service-disabled small business"], "facts_used": ["Founded in 1994 as a division of Georgetown Roofing, Inc. -> /about-us", "Operates 40,000 sq ft facility in Hyattsville, MD -> /about-us", "Veteran Owned Service Disabled Small Business -> /", "Stocks over 150 colors, materials, and gauges of architectural sheet metal -> /about-us", "24-48 hour turnaround on most orders -> /about-us", "CNC plasma cutting of architectural sheet metals -> /", "Produces items per SMACNA architectural sheet metal manual -> /about-us", "Patented fabrication process -> /about-us", "Serves mid-Atlantic region -> /about-us", "Contact Tommy Chambers -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "PAM provides a wide range of services from large volume sheet metal brake forming to custom fabrication of unusual and antique items.", "founded_year": "1994", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Veteran-owned", "Service-disabled veteran-owned", "Small business"]}'::jsonb, updated_at=now() WHERE slug='precision-architectural-metals' AND approved AND profile IS NULL;
UPDATE companies SET description='Precision Cables operates from American Fork, Utah. The company was founded by Raymond Mulitalo and Mauro Carlini, who serve as co-owners, after they experienced recurrent quality issues with previous cable suppliers and identified a market gap for reliable, high-quality cable products.

The company manufactures custom and standardized cable assemblies, wire harnesses, and electromechanical box builds. Its services include cable assembly, harness routing and assembly, over molding, testing, consignment/turnkey supply, and mechanical box builds. The facility is equipped with formboards for 100% continuity testing, harness drawing software, mating harness test fixtures, in-line inkjet circuit printing, a woven nylon braiding machine, and a height and pull tester. No headcount or volume figures are disclosed.

Precision Cables serves automotive (including farming and mining), commercial (audio, instrumentation, electro-mechanical, Ethernet, Cat 5, data), law enforcement/military (drone, autonomous, safety systems), and industrial (oil, drone, aerospace) sectors.

The company emphasizes quality assurance through IPC/WHMA-A-620 trained personnel capable of class 2 and 3 workmanship, pursuit of ISO 9001:2015 registration, RoHS compliance, and a custom-solutions approach with engineering support. It also offers consignment and turnkey supply models to streamline customer operations.', certifications=ARRAY['ISO 9001:2015 (pursuing)','IPC/WHMA-A-620','RoHS Compliant','ANSI/ASQ Z1.4-2003 (R2013)','IPC-A-620 CIT','IPC-A-620 (In-House Certified Workforce)','IPC-7711/7721 CIS','IPC/WHMA Member Facility','WHMA Member Facility']::text[], profile='{"capabilities": ["Cable assembly", "Harness routing and assembly", "Over molding", "Testing services (continuity, insulation resistance, voltage withstand, mechanical strength)", "Consignment/turnkey supply", "Mechanical box builds", "Custom cable manufacturing", "Standardized cable products", "Cable testing and certification", "Cable consultation and support", "Formboards with 100% continuity test", "Harness drawing software", "Mating harness test fixtures", "In-line inkjet circuit printing", "Woven nylon braiding", "Custom cable over molding", "Height and pull testing"], "industries": ["Automotive", "Farming", "Mining", "Commercial Audio", "Instrumentation", "Electro-Mechanical", "Ethernet", "Cat 5", "Data", "Law Enforcement", "Military", "Drone", "Autonomous", "Safety Systems", "Oil", "Aerospace"], "materials": [], "equipment": ["Formboards with 100% Continuity Test", "Harness Drawing Software", "Mating Harness Test Fixtures", "In-line Inkjet Circuit Printing", "Woven Nylon Braiding Machine", "Custom Cable Over Molding", "Height and Pull Tester"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["IPC/WHMA-A-620 trained workforce for class 2/3 workmanship", "Pursuing ISO 9001:2015 registration", "RoHS compliant manufacturing processes", "Consignment and turnkey supply options", "In-house testing with formboards, pull testers, and mating harness fixtures"], "facts_used": ["Locati