UPDATE companies SET description='Precision Electronics, Inc. (PEI) is based in Hickory, North Carolina. The company was founded in 1994 by Chris Cerrito, who remains president. It began as an industrial electronic repair business and has grown to serve manufacturers across North America and internationally.

PEI specializes in industrial electronic repair and MRO (maintenance, repair, and operations) product supply. Its repair facility handles variable frequency drives (VFDs), robot teach pendants, servo drives, touch screens, and rebuilt spares from all major brands. The company offers free repair evaluations, rush services, load testing of all drives, and software backups for drive and control systems. It also supplies industrial controls and sourcing support.

The company serves manufacturers in industries such as paper, plastics, building products, wood products, and general industrial automation. Named customers include International Paper, Munot Plastics, Boral Building Products, Plasman Group, Cummins-Wagner Co., Atlas Machine & Supply, and Ed McGinnis Wood Products.

PEI emphasizes long-term relationships over quick sales, honoring warranties and prioritizing quality over shortcuts. It positions itself as a single source for industrial controls, supplies, and repairs, offering like-new performance at 30–65% of the cost of new equipment.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Industrial electronic repair", "VFD repair", "Robot teach pendant repair", "Servo drive repair", "Touch screen repair", "Rebuilt spares supply", "MRO product supply", "Industrial controls sourcing", "Free repair evaluations", "Rush repair services", "Load testing of drives", "Drive and control software backup", "No RMA required for repairs"], "industries": ["Manufacturing"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Free repair evaluations with no RMA required", "All drives load tested before return", "Drive and control software backups provided", "Repairs typically 30\u201365% of new equipment cost", "Rush services available for emergency downtime"], "facts_used": ["Headquarters in Hickory, NC -> db", "Founded in 1994 by Chris Cerrito -> /about", "Provides MRO products and service to manufacturers -> db, /about", "Repairs VFDs, robot teach pendants, servo drives, touch screens, rebuilt spares -> db", "Free repair evaluations, rush services, load testing, software backups, no RMA -> /", "Serves thousands of manufacturers across North America and internationally -> /about", "Customers: International Paper, Munot Plastics, Boral Building Products, Plasman Group, Cummins-Wagner Co., Atlas Machine & Supply, Ed McGinnis Wood Products -> /, /about", "Emphasis on long-term relationships, warranty, quality -> /about", "Single source for industrial controls, supplies, repairs -> /about", "Like-new performance at 30-65% of new cost -> db, /", "American-owned, locally-based -> /", "All drives load tested -> /", "Drive and control software backups -> /", "Quality repairs the first time -> /", "No RMA needed -> /", "Rush services available -> /, db"], "company_type": "Installer / service company", "makes_products": "no", "type_evidence": "Precision Electronics, Inc. provides MRO products and service to thousands of manufacturers throughout North America.", "founded_year": "1994", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='precision-electronics-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Precision Fabrics Group is headquartered in Greensboro, North Carolina, with manufacturing plants in North Carolina and Virginia. The company was created in 1988 when Lanty L. Smith led a leveraged buyout of the Precision Fabrics Division from Burlington Industries, and it remains a privately held business today. Smith, a former president of Burlington, founded the company to acquire the existing textile operations and steer them toward engineered materials.

The company produces highly technical woven and nonwoven engineered materials. Its Vinton, Virginia plant specializes in weaving continuous-filament fabrics, while the Greensboro, North Carolina facility focuses on a broad range of nonwoven products. Core processes include fine-filament weaving, finishing, and the application of chemistries and laminations to nonwoven substrates. Precision Fabrics employs approximately 600 associates and offers a wide spectrum of technical properties such as acoustic absorption, flame resistance, antimicrobial protection, electromagnetic interference shielding, and fluid repellency.

Precision Fabrics serves high-performance industries including aerospace, military, medical, protective garments, automotive, home appliances, and wind energy. Its materials are used in applications such as acoustic fabrics for automotive noise control, emergency escape chute components, therapeutic bedding, medical fabrics, protective apparel, and window treatment fabrics. The company maintains long-standing customer relationships through collaborative R&D and a focus on product quality.

Precision Fabrics was the first ISO-qualified textile supplier in the United States, achieving ISO 9001 registration in 1993 and updating to ISO 9001:2015 in 2018. The company says its differentiation lies in the breadth of its technical capabilities, the depth of its team''s expertise, and a commitment to innovation that drives problem-solving across diverse markets.', certifications=ARRAY['ISO 9001:2015','ISO 9001']::text[], profile='{"capabilities": ["Fine filament weaving", "Finishing of woven fabrics", "Applying chemistries to nonwoven substrates", "Lamination of nonwoven substrates", "Acoustic absorption", "Adhesion promotion", "Air dispersion", "Allergen barriers", "Anti-fungal treatment", "Anti-microbial treatment", "Anti-static treatment", "Blood barrier", "Bond release", "Chemical barrier & resistance", "Conductivity", "Corrosion protection", "Electromagnetic interference shielding", "Environmental protection", "Flame barrier & resistance", "Fluid absorption & repellency", "Improved durability", "Light control", "Moisture absorption & repellency", "Moisture control"], "industries": ["aerospace", "military", "medical", "protective garments", "automotive", "home appliances", "wind energy"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["First ISO-qualified textile supplier in the USA", "ISO 9001 registered since 1993, certified to ISO 9001:2015", "Broad spectrum of technical properties on both woven and nonwoven materials", "Specialized in technically challenging continuous-filament fabrics (Vinton, VA plant)", "World-class range of nonwoven products (Greensboro, NC facility)"], "facts_used": ["Headquarters in Greensboro, NC with plants in North Carolina and Virginia -> /about-us", "Founded in 1988 via leveraged buyout from Burlington Industries by Lanty L. Smith -> /about-us", "Privately held company -> /about-us", "Approximately 600 employees -> /about-us", "Vinton, VA plant specializes in continuous-filame